Przykladowe rozwiazanie (C++):
long int kw(long int n) { return n*n; }
long int f(long int n) {
  int i, k;
  if (n==1 || n==2) return 1;
  else if (n%2==0) {
    i = n/2+1;
    k = n/2-1;
    return kw(f(i)) - kw(f(k));
  } else {
    i = (n+1)/2;
    k = (n+1)/2-1;
    return kw(f(i)) + kw(f(k));
  }
}

Uwaga: dopuszczamy zastosowanie funkcji potegowania wbudowanej w jezyk.
